    抛 ValueError，且此时尚未创建输出文件。
    """
    conn, cursor, headers = _prepare_query(
        db_path, sql_text, params, null_text, output_path
    )
    try:
        rows = _fetch_query(cursor)
    finally:
        conn.close()
    return headers, rows

