        parser.error(
            "--preview 需要正整数 N（缺少值、零、负数或非整数均拒绝）：%r"
            % args.preview
        )
    args.preview = int(args.preview)
    if args.format == "html":
        parser.error("--preview 仅支持 CSV：请省略 --format 或使用 --format csv")
